// ─────────────────────────────────────────────────────────────────────
// Node: Build Run Context                     Mode: Run Once for All Items
// Repo: n8n-google-postmaster-tools-deliverability-alert-bot · dhRobin Systems
// Decides which domains to check, the date window (Postmaster data lags a
// day or two, so the window looks back LOOKBACK_DAYS) and the run mode.
// Domains come from POSTMASTER_DOMAINS (least privilege, default) or, with
// POSTMASTER_DISCOVER_DOMAINS=true, from GET /v2/domains.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

let crypto = null; try { crypto = require('crypto'); } catch (e) { crypto = null; }
const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const LOOKBACK = Math.min(30, Math.max(3, num('LOOKBACK_DAYS', 8)));
const first = $input.first().json || {};
const fixtures = SANDBOX_MODE ? first.sandboxFixtures || null : null;
const domainOk = (d) => /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(d);
let domains = csv('POSTMASTER_DOMAINS', '').map((d) => d.toLowerCase().replace(/^domains\//, '')).filter((d) => domainOk(d) && !/^your_/i.test(d));
if (SANDBOX_MODE && !domains.length && fixtures) domains = fixtures.domains.map((d) => d.name);
const today = fixtures && fixtures.today ? new Date(`${fixtures.today}T00:00:00Z`) : new Date();
const dayStart = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()));
const d = (offset) => { const x = new Date(dayStart.getTime() - offset * 86400000); return { year: x.getUTCFullYear(), month: x.getUTCMonth() + 1, day: x.getUTCDate() }; };
let runId; try { runId = 'pm_' + crypto.randomUUID(); } catch (e) { runId = 'pm_' + Date.now().toString(36); }
return [{ json: {
  run: { runId, startedAt: new Date().toISOString(), mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live', sandboxMode: SANDBOX_MODE, dryRun: DRY_RUN, checkDate: dayStart.toISOString().slice(0, 10) },
  window: { start: d(LOOKBACK), end: d(1), lookbackDays: LOOKBACK },
  domains,
  discover: !SANDBOX_MODE && flag('POSTMASTER_DISCOVER_DOMAINS', false),
  sandboxFixtures: fixtures,
} }];

// ─────────────────────────────────────────────────────────────────────
// Node: Simulate Postmaster API (Sandbox)     Mode: Run Once for All Items
// Fictional domains in the exact v2 response shapes: QueryDomainStatsResponse
// (domainStats[].{name, metric, date, value.doubleValue}) and
// DomainComplianceStatus (complianceData.{rowData, deliverabilityStatusVerdict}).
// ─────────────────────────────────────────────────────────────────────
const ctx = $input.first().json;
const fx = ctx.sandboxFixtures || { domains: [] };
const out = [];
for (const dom of fx.domains) {
  if (dom.error) { out.push({ json: { domain: dom.name, simulated: { stats: { statusCode: dom.error, body: { error: { code: dom.error, status: 'PERMISSION_DENIED', message: 'The caller does not have permission' } } }, compliance: { statusCode: dom.error, body: {} } } } }); continue; }
  const domainStats = [];
  (dom.days || []).forEach((day, i) => {
    const date = { year: Number(day.date.slice(0, 4)), month: Number(day.date.slice(5, 7)), day: Number(day.date.slice(8, 10)) };
    for (const [metric, v] of Object.entries(day.metrics)) domainStats.push({ name: `domains/${dom.name}/domainStats/${day.date.replace(/-/g, '')}-${metric}`, metric, date, value: { doubleValue: v } });
  });
  out.push({ json: { domain: dom.name, simulated: {
    stats: { statusCode: 200, body: { domainStats, nextPageToken: '' } },
    compliance: dom.compliance ? { statusCode: 200, body: { name: `domains/${dom.name}/complianceStatus`, complianceData: dom.compliance } } : { statusCode: 404, body: {} },
  } } });
}
return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Build Domain Queries                  Mode: Run Once for All Items
// One item per domain with its domainStats:query body. With discovery on,
// verified domains from GET /v2/domains are added to the configured list.
// Metrics (v2 StandardMetric, one query per domain, DAILY):
//   spam_rate         SPAM_RATE
//   auth_spf/dkim/dmarc AUTH_SUCCESS_RATE  auth_type = "spf" | "dkim" | "dmarc"
//   tls_inbound       TLS_ENCRYPTION_RATE  traffic_direction = "inbound" (your mail into Gmail)
//   err_total         DELIVERY_ERROR_RATE  (all types)
//   err_rep_domain    DELIVERY_ERROR_RATE  reject · low_domain_reputation
//   err_rep_ip        DELIVERY_ERROR_RATE  reject · low_ip_reputation
//   err_temp          DELIVERY_ERROR_RATE  temp_fail
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const MAX = Math.max(1, num('MAX_DOMAINS_PER_RUN', 50));
const ctx = $('Build Run Context').first().json;
const domains = [...ctx.domains];
const discovery = { used: false, status: null, skipped: 0 };
if (ctx.discover) {
  let res = null; try { res = $('List Postmaster Domains').first().json; } catch (e) { res = null; }
  discovery.used = true; discovery.status = res ? res.statusCode || null : null;
  const list = res && Number(res.statusCode) === 200 && res.body && Array.isArray(res.body.domains) ? res.body.domains : [];
  for (const x of list) {
    const name = String(x.name || '').replace(/^domains\//, '').toLowerCase();
    if (!name) continue;
    if (x.verificationState && !/^VERIFIED/.test(String(x.verificationState))) { discovery.skipped++; continue; }
    if (!domains.includes(name)) domains.push(name);
  }
}
const m = (name, standardMetric, filter) => ({ name, baseMetric: { standardMetric }, ...(filter ? { filter } : {}) });
const metricDefinitions = [
  m('spam_rate', 'SPAM_RATE'),
  m('auth_spf', 'AUTH_SUCCESS_RATE', 'auth_type = "spf"'),
  m('auth_dkim', 'AUTH_SUCCESS_RATE', 'auth_type = "dkim"'),
  m('auth_dmarc', 'AUTH_SUCCESS_RATE', 'auth_type = "dmarc"'),
  m('tls_inbound', 'TLS_ENCRYPTION_RATE', 'traffic_direction = "inbound"'),
  m('err_total', 'DELIVERY_ERROR_RATE'),
  m('err_rep_domain', 'DELIVERY_ERROR_RATE', 'error_type = "reject" AND error_reason = "low_domain_reputation"'),
  m('err_rep_ip', 'DELIVERY_ERROR_RATE', 'error_type = "reject" AND error_reason = "low_ip_reputation"'),
  m('err_temp', 'DELIVERY_ERROR_RATE', 'error_type = "temp_fail"'),
];
if (!domains.length) return [{ json: { domain: null, skip: true, discovery, reason: ctx.discover ? 'no verified domains returned by GET /v2/domains' : 'POSTMASTER_DOMAINS is empty' } }];
return domains.slice(0, MAX).map((domain) => ({ json: { domain, path: encodeURIComponent(domain), discovery,
  query: { metricDefinitions, timeQuery: { dateRanges: { dateRanges: [{ start: ctx.window.start, end: ctx.window.end }] } }, aggregationGranularity: 'DAILY', pageSize: 200 } } }));

// ─────────────────────────────────────────────────────────────────────
// Node: Domain Health & Alert Evaluator       Mode: Run Once for All Items
// Google retired Domain and IP Reputation in Postmaster Tools v2, so I grade
// each domain HIGH / MEDIUM / LOW / BAD from the signals v2 still exposes:
//   spam rate (latest day + spike vs. baseline) · reputation-driven rejects
//   (low_domain_reputation, low_ip_reputation) · SPF/DKIM/DMARC success ·
//   inbound TLS encryption rate · total delivery errors · compliance status.
// The worst rule wins. Alerts fire on drops into MEDIUM/LOW/BAD, spam spikes,
// repeats while degraded (REPEAT_ALERT_DAYS), recoveries and API errors.
// Builds one Slack Block Kit message for the whole run.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const T = {
  spamWarn: num('SPAM_RATE_WARN', 0.001), spamCrit: num('SPAM_RATE_CRITICAL', 0.003), spamSevere: num('SPAM_RATE_SEVERE', 0.006),
  spikeMult: num('SPAM_SPIKE_MULTIPLIER', 2), spikeMin: num('SPAM_SPIKE_MIN_RATE', 0.0005),
  repWarn: num('REPUTATION_REJECT_WARN', 0), repCrit: num('REPUTATION_REJECT_CRITICAL', 0.01), repSevere: num('REPUTATION_REJECT_SEVERE', 0.05),
  authMin: num('AUTH_SUCCESS_MIN', 0.98), tlsMin: num('TLS_ENCRYPTION_MIN', 0.99), tlsCrit: num('TLS_ENCRYPTION_CRITICAL', 0.9),
  errWarn: num('DELIVERY_ERROR_WARN', 0.02), errCrit: num('DELIVERY_ERROR_CRITICAL', 0.1),
};
const REPEAT_DAYS = Math.max(1, num('REPEAT_ALERT_DAYS', 3));
const RECOVERY = flag('NOTIFY_ON_RECOVERY', true);
const ALERT_NO_DATA = flag('ALERT_ON_NO_DATA', false);
const MASK_SLACK = flag('SLACK_MASK_DOMAINS', false);
const MENTION = env('SLACK_MENTION_ON_LOW', '');
const MAX_IN_MESSAGE = 10;
const RANK = { HIGH: 0, MEDIUM: 1, LOW: 2, BAD: 3 };

const ctx = $('Build Run Context').first().json;
const items = $input.all();
const sandbox = !!(items[0] && items[0].json.simulated);
let pairs;
let configError = null;
if (sandbox) pairs = items.map((i) => ({ domain: i.json.domain, stats: i.json.simulated.stats, compliance: i.json.simulated.compliance }));
else {
  const queries = $('Build Domain Queries').all();
  let stats = [];
  try { stats = $('Query Domain Stats').all(); } catch (e) { stats = []; }
  if (queries[0] && queries[0].json.skip) { configError = queries[0].json.reason; pairs = []; }
  else pairs = queries.map((q, i) => ({ domain: q.json.domain, stats: stats[i] ? stats[i].json : null, compliance: items[i] ? items[i].json : null }));
}
let state = {};
if (sandbox) state = (ctx.sandboxFixtures && ctx.sandboxFixtures.previousState) || {};
else { try { state = JSON.parse(JSON.stringify($getWorkflowStaticData('global').postmasterState || {})); } catch (e) { state = {}; } }

const rate = (v) => { if (!v) return null; let n = v.doubleValue ?? v.floatValue ?? (v.intValue !== undefined ? Number(v.intValue) : null); n = Number(n); if (!Number.isFinite(n)) return null; return n > 1 ? n / 100 : n; };
const iso = (d) => (d ? `${d.year}-${String(d.month).padStart(2, '0')}-${String(d.day).padStart(2, '0')}` : null);
const pct = (v, dp = 2) => (v === null || v === undefined ? 'n/a' : `${(v * 100).toFixed(dp)}%`);
const worst = (a, b) => (RANK[b] > RANK[a] ? b : a);

function evaluate(p) {
  const e = { domain: p.domain, grade: 'HIGH', status: 'ok', dataDate: null, metrics: {}, baseline: {}, findings: [], compliance: null, errors: [] };
  const sc = p.stats ? Number(p.stats.statusCode) : 0;
  if (sc !== 200) {
    e.status = 'error'; e.grade = null;
    const msg = p.stats && p.stats.body && p.stats.body.error ? `${p.stats.body.error.status || ''} ${p.stats.body.error.message || ''}`.trim() : 'no response';
    e.errors.push(`domainStats:query HTTP ${sc || 'n/a'} ${msg}`.slice(0, 200));
    return e;
  }
  const byDate = {};
  for (const s of (p.stats.body && p.stats.body.domainStats) || []) { const d = iso(s.date); if (!d) continue; (byDate[d] = byDate[d] || {})[s.metric] = rate(s.value); }
  const dates = Object.keys(byDate).sort();
  if (!dates.length) { e.status = 'no_data'; e.grade = null; return e; }
  const latest = dates[dates.length - 1];
  e.dataDate = latest; e.metrics = byDate[latest]; e.daysWithData = dates.length;
  const prior = dates.slice(0, -1).map((d) => byDate[d].spam_rate).filter((v) => v !== null && v !== undefined);
  e.baseline.spamRate = prior.length >= 3 ? prior.reduce((a, b) => a + b, 0) / prior.length : null;
  const m = e.metrics;
  const add = (grade, kind, message, value, threshold) => { e.grade = worst(e.grade, grade); e.findings.push({ grade, kind, message, value, threshold }); };

  if (m.spam_rate != null) {
    if (m.spam_rate >= T.spamSevere) add('BAD', 'spam_rate', `Spam rate ${pct(m.spam_rate)} is far above Google's 0.30% limit`, m.spam_rate, T.spamSevere);
    else if (m.spam_rate >= T.spamCrit) add('LOW', 'spam_rate', `Spam rate ${pct(m.spam_rate)} at or above ${pct(T.spamCrit)}`, m.spam_rate, T.spamCrit);
    else if (m.spam_rate >= T.spamWarn) add('MEDIUM', 'spam_rate', `Spam rate ${pct(m.spam_rate)} above the ${pct(T.spamWarn)} target`, m.spam_rate, T.spamWarn);
    if (e.baseline.spamRate !== null && m.spam_rate >= Math.max(T.spikeMin, T.spikeMult * e.baseline.spamRate)) {
      e.spamSpike = true;
      add(m.spam_rate >= T.spamWarn ? 'MEDIUM' : 'HIGH', 'spam_spike', `Spam spike: ${pct(m.spam_rate)} vs ${pct(e.baseline.spamRate)} average over the prior ${prior.length} days`, m.spam_rate, T.spikeMult * e.baseline.spamRate);
    }
  }
  for (const [k, label] of [['err_rep_domain', 'low domain reputation'], ['err_rep_ip', 'low IP reputation']]) {
    const v = m[k];
    if (v == null || v <= T.repWarn) continue;
    add(v >= T.repSevere ? 'BAD' : v >= T.repCrit ? 'LOW' : 'MEDIUM', k, `Gmail rejected ${pct(v)} of mail for ${label}`, v, v >= T.repSevere ? T.repSevere : v >= T.repCrit ? T.repCrit : T.repWarn);
  }
  for (const [k, label] of [['auth_spf', 'SPF'], ['auth_dkim', 'DKIM'], ['auth_dmarc', 'DMARC']]) if (m[k] != null && m[k] < T.authMin) add('MEDIUM', k, `${label} success ${pct(m[k], 1)} below ${pct(T.authMin, 0)}`, m[k], T.authMin);
  if (m.tls_inbound != null && m.tls_inbound < T.tlsMin) add(m.tls_inbound < T.tlsCrit ? 'LOW' : 'MEDIUM', 'tls', `TLS encryption ${pct(m.tls_inbound, 1)} below ${pct(T.tlsMin, 0)} (unencrypted delivery to Gmail)`, m.tls_inbound, T.tlsMin);
  if (m.err_total != null && m.err_total >= T.errWarn) add(m.err_total >= T.errCrit ? 'LOW' : 'MEDIUM', 'delivery_errors', `Delivery errors ${pct(m.err_total, 1)} of traffic${m.err_temp ? ` (temp-fail ${pct(m.err_temp, 1)})` : ''}`, m.err_total, T.errWarn);

  const c = p.compliance && Number(p.compliance.statusCode) === 200 && p.compliance.body ? p.compliance.body.complianceData : null;
  if (c) {
    const needs = (c.rowData || []).filter((r) => r.status && r.status.status === 'NEEDS_WORK').map((r) => String(r.requirement || 'requirement').replace(/_/g, ' ').toLowerCase());
    const verdict = c.deliverabilityStatusVerdict && c.deliverabilityStatusVerdict.state ? c.deliverabilityStatusVerdict.state.status : null;
    e.compliance = { needsWork: needs, deliverability: verdict, reason: c.deliverabilityStatusVerdict ? c.deliverabilityStatusVerdict.reason || null : null };
    if (needs.length) add('MEDIUM', 'compliance', `Sender requirements need work: ${needs.join(', ')}`, needs.length, 0);
    if (verdict === 'NEEDS_WORK') add('MEDIUM', 'deliverability_verdict', `Deliverability verdict: needs work${e.compliance.reason ? ` (${String(e.compliance.reason).replace(/_/g, ' ').toLowerCase()})` : ''}`, null, null);
  } else if (p.compliance && Number(p.compliance.statusCode) !== 404) e.errors.push(`complianceStatus HTTP ${p.compliance.statusCode || 'n/a'}`);
  return e;
}

// Sandbox runs use the fixture date, so the repeat/recovery rules behave the same whenever you test.
const nowMs = sandbox && ctx.sandboxFixtures && ctx.sandboxFixtures.today ? Date.parse(`${ctx.sandboxFixtures.today}T07:17:00Z`) : Date.now();
const evaluations = pairs.map(evaluate);
const alerts = [];
const nextState = { ...state };
for (const e of evaluations) {
  const prev = state[e.domain] || null;
  let reason = null;
  const newSpike = !prev || prev.spikeDataDate !== e.dataDate; // one spike alert per data day
  if (e.status === 'error') reason = 'api_error';
  else if (e.status === 'no_data') reason = ALERT_NO_DATA && prev && prev.grade ? 'no_data' : null;
  else if (RANK[e.grade] >= 1) {
    const prevRank = prev && prev.grade && RANK[prev.grade] !== undefined ? RANK[prev.grade] : -1;
    if (RANK[e.grade] > prevRank) reason = prev && prev.grade ? 'degraded' : 'degraded_first_check';
    else if (e.spamSpike && newSpike) reason = 'spam_spike';
    else if (!prev || !prev.lastAlertAt || nowMs - Date.parse(prev.lastAlertAt) >= REPEAT_DAYS * 86400000) reason = 'still_degraded';
  } else if (e.spamSpike && newSpike) reason = 'spam_spike';
  else if (RECOVERY && prev && prev.grade && RANK[prev.grade] >= 1) reason = 'recovered';
  e.previousGrade = prev ? prev.grade || null : null;
  e.alertReason = reason;
  if (reason) alerts.push(e);
  nextState[e.domain] = { grade: e.status === 'ok' ? e.grade : prev ? prev.grade : null, checkedAt: new Date(nowMs).toISOString(), dataDate: e.dataDate || (prev && prev.dataDate) || null,
    lastAlertAt: reason ? new Date(nowMs).toISOString() : prev ? prev.lastAlertAt || null : null,
    spikeDataDate: e.spamSpike ? e.dataDate : prev ? prev.spikeDataDate || null : null };
}

// ── Slack Block Kit ───────────────────────────────────────────────────
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const show = (d) => (MASK_SLACK ? d.replace(/^([^.]{1,2})[^.]*/, '$1•••') : d);
const EMOJI = { HIGH: '🟢', MEDIUM: '🟡', LOW: '🟠', BAD: '🔴' };
const ACTION = {
  spam_rate: 'Pause cold or low-engagement segments, check list sources, keep complaints under 0.10%.',
  spam_spike: 'Find the campaign or segment sent on the spike day and stop it; review recent list imports.',
  err_rep_domain: 'Gmail is rejecting on domain reputation: cut volume, send only to engaged recipients, warm back up slowly.',
  err_rep_ip: 'Gmail is rejecting on IP reputation: check your ESP pool or dedicated IP, slow down, check blocklists.',
  auth_spf: 'Check SPF includes for every sending service.', auth_dkim: 'Check DKIM signing and key rotation at every sending service.',
  auth_dmarc: 'Check DMARC alignment of the From domain with SPF/DKIM.', tls: 'Make sure every sending MTA uses TLS to Gmail.',
  delivery_errors: 'Open Postmaster Tools → Delivery errors for the reasons.', compliance: 'Fix the sender requirements listed in Compliance status.',
  deliverability_verdict: 'Review the Deliverability analysis in Postmaster Tools.',
};
if (configError) alerts.push({ domain: '(configuration)', alertReason: 'api_error', errors: [configError], findings: [], metrics: {}, baseline: {} });
const degraded = alerts.filter((a) => a.alertReason !== 'recovered' && a.alertReason !== 'api_error');
const recovered = alerts.filter((a) => a.alertReason === 'recovered');
const errored = alerts.filter((a) => a.alertReason === 'api_error');
let slackMessage = null;
if (alerts.length) {
  const worstGrade = degraded.reduce((g, a) => (a.grade ? worst(g, a.grade) : g), 'HIGH');
  const title = degraded.length ? `${EMOJI[worstGrade]} Gmail deliverability: ${degraded.length} domain${degraded.length === 1 ? '' : 's'} need attention` : recovered.length ? '🟢 Gmail deliverability recovered' : '⚠️ Postmaster Tools check failed';
  const blocks = [{ type: 'header', text: { type: 'plain_text', text: title.slice(0, 150), emoji: true } }];
  if (MENTION && degraded.some((a) => RANK[a.grade] >= 2)) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `${MENTION} a domain is at LOW or BAD` } });
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `Check ${esc(ctx.run.checkDate)} · data through ${esc(evaluations.map((x) => x.dataDate).filter(Boolean).sort().pop() || 'n/a')} · ${evaluations.length} domains checked · mode ${esc(ctx.run.mode)}` }] });
  for (const a of degraded.slice(0, MAX_IN_MESSAGE)) {
    const m = a.metrics;
    const why = { degraded: `dropped ${a.previousGrade} → *${a.grade}*`, degraded_first_check: `*${a.grade}* on first check`, spam_spike: `spam spike (still *${a.grade}*)`, still_degraded: `still *${a.grade}*`, no_data: 'no data today' }[a.alertReason] || a.alertReason;
    blocks.push({ type: 'divider' });
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `${EMOJI[a.grade] || '⚪'} *${esc(show(a.domain))}*: ${why} · data ${esc(a.dataDate || 'n/a')}` },
      fields: [
        { type: 'mrkdwn', text: `*Spam rate*\n${pct(m.spam_rate)}${a.baseline.spamRate !== null && a.baseline.spamRate !== undefined ? ` (avg ${pct(a.baseline.spamRate)})` : ''}` },
        { type: 'mrkdwn', text: `*Reputation rejects*\ndomain ${pct(m.err_rep_domain)} · IP ${pct(m.err_rep_ip)}` },
        { type: 'mrkdwn', text: `*Auth (SPF/DKIM/DMARC)*\n${pct(m.auth_spf, 1)} / ${pct(m.auth_dkim, 1)} / ${pct(m.auth_dmarc, 1)}` },
        { type: 'mrkdwn', text: `*TLS · delivery errors*\n${pct(m.tls_inbound, 1)} · ${pct(m.err_total, 1)}` },
      ] });
